def classify(r):
    code = r.status_code
    if 200 <= code < 300:
        return "ok"
    if code == 401:
        return "refresh token, then retry once"
    if code == 429:
        wait = r.headers.get("Retry-After", "a few")
        return f"rate limited: wait {wait} seconds and retry"
    if code in (500, 502, 503, 504):
        return "server trouble: retry with backoff"
    if 400 <= code < 500:
        return f"our request is wrong, do not retry: {r.text[:200]}"
    return "unexpected"

