import requests

def sync_invoices(url):
    for attempt in range(2):
        r = requests.get(url, timeout=10)
        if r.status_code == 503 and attempt == 0:
            continue                       # retry once
        r.raise_for_status()
        return r.json()["invoices"]

# test_invoices.py
from unittest.mock import patch, Mock
from invoices import sync_invoices

@patch("invoices.requests.get")
def test_retries_once_on_503(mock_get):
    busy = Mock(status_code=503)
    ok = Mock(status_code=200)
    ok.json.return_value = {"invoices": [{"id": 1}, {"id": 2}]}
    mock_get.side_effect = [busy, ok]      # first call, second call
    assert len(sync_invoices("https://fin.example.com/v1/invoices")) == 2
    assert mock_get.call_count == 2

