from typing import Protocol, Callable
from dataclasses import dataclass

@dataclass
class Order:
    id: str
    total: float

class OrderSource(Protocol):                      # the interface our code wants
    def get_orders(self) -> list[Order]: ...

class RetailerAApi:                               # ADAPTER for a REST API
    def __init__(self, client): self.client = client
    def get_orders(self):
        return [Order(r["orderId"], r["grandTotal"]) for r in self.client.fetch_all()]

class InMemoryOrders:                             # REPOSITORY-style fake for tests
    def __init__(self, orders): self.orders = orders
    def get_orders(self): return list(self.orders)

ROUNDING: dict[str, Callable[[float], float]] = {  # STRATEGY chosen by config
    "cent":  lambda x: round(x, 2),
    "5p":    lambda x: round(x * 20) / 20,
}

def revenue(source: OrderSource, rounding: str) -> float:
    return ROUNDING[rounding](sum(o.total for o in source.get_orders()))

print(revenue(InMemoryOrders([Order("1", 10.02), Order("2", 4.99)]), "5p"))

from datetime import date

class BadRow(ValueError):
    pass

def validate(row: dict, line_no: int) -> dict:
    if not row.get("claim_id"):                       # guard clause
        raise BadRow(f"line {line_no}: claim_id missing")
    try:
        amount = float(row["amount"])
    except (KeyError, ValueError):
        raise BadRow(f"line {line_no}: amount not a number: {row.get('amount')!r}")
    if amount <= 0:
        raise BadRow(f"line {line_no}: amount must be positive, got {amount}")
    when = date.fromisoformat(row["incident_date"])
    if when > date.today():
        raise BadRow(f"line {line_no}: incident_date in the future: {when}")
    return {"claim_id": row["claim_id"], "amount": amount, "incident_date": when}

rows = [{"claim_id": "C1", "amount": "120.50", "incident_date": "2026-03-02"},
        {"claim_id": "", "amount": "80", "incident_date": "2026-04-11"}]
good, rejects = [], []
for i, row in enumerate(rows, start=2):               # line 1 is the header
    try:
        good.append(validate(row, i))
    except (BadRow, KeyError, ValueError) as e:
        rejects.append((i, str(e)))                   # keep it, with the reason
print(f"{len(good)} loaded, {len(rejects)} rejected")
